import asyncio,json
from playwright.async_api import async_playwright
B='http://localhost:8765/insa-hoedok/'
SNAP="JSON.stringify({add:U.add,ov:U.ov,res:U.res,qres:U.qres})"
VIS="JSON.stringify(items('blanks').filter(b=>b.mine||b.core).map(b=>[b.id,b.p,b.r]))"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
        ctx = await b.new_context(viewport={'width':1400,'height':1000}); page = await ctx.new_page()
        errs=[];page.on('pageerror',lambda e:errs.append(str(e)))
        page.on('dialog', lambda d: asyncio.ensure_future(d.accept()))
        # A. 1편만 있는 상태 (2편은 목록에만 있음)
        await page.goto(B+'index.html#stay'); await page.wait_for_timeout(800)
        await page.set_input_files('#zipIn','/home/claude/test/test_r01.zip')
        await page.wait_for_selector('.pb button', timeout=60000); await page.click('.pb button'); await page.wait_for_timeout(800)
        print('A index rows:',await page.evaluate("[...document.querySelectorAll('#ctRows .row')].map(r=>r.innerText.replace(/\\n/g,' '))"), '| go disabled:',await page.evaluate("document.querySelector('#go').disabled"),'|',await page.inner_text('#goNote'))
        await page.screenshot(path='A_index.png')
        await page.goto(B+'app.html'); await page.wait_for_timeout(4000)
        print('A rounds',await page.evaluate("D.rounds.map(r=>[r.key,r.start,r.n])"),'pages',await page.evaluate("D.pages.length"),'label',await page.inner_text('#rangeLbl'))
        snapA=await page.evaluate(SNAP); visA=await page.evaluate(VIS)
        print('A mine/core visible',len(json.loads(visA)), 'quiz',await page.evaluate("D.quiz.items.map(i=>qLbl(i.q))"))
        # B. 2편 묶음 넣기
        await page.goto(B+'index.html#stay'); await page.wait_for_timeout(800)
        await page.set_input_files('#zipIn','/home/claude/test/교재_r02.zip'); await page.wait_for_timeout(6000)
        print('B index rows:',await page.evaluate("[...document.querySelectorAll('#ctRows .row')].map(r=>r.innerText.replace(/\\n/g,' '))"),'| pb buttons:',await page.evaluate("document.querySelectorAll('.pb').length"),'| rec:',await page.inner_text('#rcNote'))
        await page.screenshot(path='B_index.png')
        await page.goto(B+'app.html'); await page.wait_for_timeout(5000)
        print('B rounds',await page.evaluate("D.rounds.map(r=>[r.key,r.part,r.start,r.n])"),'pages',await page.evaluate("D.pages.length"),'label',await page.inner_text('#rangeLbl'))
        snapB=await page.evaluate(SNAP); visB=await page.evaluate(VIS)
        print('B record identical:',snapA==snapB,'| visible mine/core identical:',visA==visB)
        print('B heads r02',await page.evaluate("D.heads.filter(h=>h.id.startsWith('r02:')).length"),'blanks r02',await page.evaluate("D.blanks.filter(h=>h.id.startsWith('r02:')).map(b=>b.q).reduce((a,q)=>(a[q]=(a[q]||0)+1,a),{})"),'r01 blanks by q',await page.evaluate("D.blanks.filter(h=>!h.id.startsWith('r02:')).map(b=>b.q).reduce((a,q)=>(a[q]=(a[q]||0)+1,a),{})"))
        print('B quiz',await page.evaluate("D.quiz.title+' | '+D.quiz.items.map(i=>qLbl(i.q)+'/'+i.key+'/'+i.dir).join(', ')"))
        print('B qres kept',await page.evaluate("JSON.stringify(U.qres)"),'ov del still hides b1-003:',await page.evaluate("!items('blanks').some(b=>b.id==='b1-003')"))
        print('B page labels',await page.evaluate("[49,50,53,79].map(pageLabel)"),'src',await page.evaluate("D.pages[50].src"))
        # 2편 쪽에 내 빈칸 만들기 → 저장 형식 확인
        await page.evaluate("setMode('blank')"); await page.evaluate("setMK('mine')"); await page.wait_for_timeout(2500)
        await page.evaluate("jumpTo(57,0.4)"); await page.wait_for_timeout(1500)
        pt=await page.evaluate("(()=>{const w=wordsOf(57).find(w=>w[1]>0.52&&w[2]>0.05);const r=PG[57].box.getBoundingClientRect();return [r.left+(w[0]+w[2]/2)*r.width,r.top+(w[1]+w[3]/2)*r.height]})()")
        await page.mouse.click(pt[0],pt[1]); await page.wait_for_timeout(800)
        nb=await page.evaluate("JSON.stringify(U.add.blanks.slice(-1)[0])"); print('B new mine on r02:',nb)
        await page.evaluate("setMK(false)"); await page.wait_for_timeout(1500)
        await page.screenshot(path='B_p57.png')
        # 문항별 보기
        await page.evaluate("BQ=2001;renderAll();updateSub()"); await page.wait_for_timeout(500)
        print('B BQ=2001 blanks',await page.evaluate("items('blanks').filter(inBQ).length"),'BQ=1',await page.evaluate("(BQ=1,items('blanks').filter(inBQ).length)"))
        await page.evaluate("BQ=0;renderAll();updateSub();jumpTo(62,0.05)"); await page.wait_for_timeout(1500); await page.screenshot(path='B_p62.png')
        await page.evaluate("jumpTo(70,0.05)"); await page.wait_for_timeout(1500); await page.screenshot(path='B_p70.png')
        await page.evaluate("setSide('sc')"); await page.wait_for_timeout(600); await page.screenshot(path='B_scholars.png')
        await page.evaluate("setSide('toc')"); await page.wait_for_timeout(600); await page.screenshot(path='B_toc.png')
        await page.evaluate("openQuiz()"); await page.wait_for_timeout(1500); await page.screenshot(path='B_quiz.png')
        await page.evaluate("openQuiz(2001)"); await page.wait_for_timeout(1200); await page.click('#sheet >> text=답 보기'); await page.wait_for_timeout(800); await page.screenshot(path='B_quiz1.png')
        await page.evaluate("openQuiz(2003)"); await page.wait_for_timeout(1200); await page.click('#sheet >> text=답 보기'); await page.wait_for_timeout(800); await page.screenshot(path='B_quiz3.png')
        await page.click('#sheet .qj .o'); await page.wait_for_timeout(500)
        print('B qres after',await page.evaluate("JSON.stringify(U.qres)"))
        await page.evaluate("$('#sheet').hidden=true"); await page.wait_for_timeout(2500)
        # 새로고침 뒤 보존
        await page.reload(); await page.wait_for_timeout(5000)
        print('B reload: mine/core',await page.evaluate("items('blanks').filter(b=>b.mine||b.core).length"),'r02 mine p',await page.evaluate("items('blanks').filter(b=>b.rk==='r02').map(b=>b.p)"))
        # C. 2편 묶음이 기기에서 사라진 경우
        await page.evaluate("(async()=>{const c=await caches.open('insa-content-v1');for(const k of await c.keys())if(k.url.includes('r02'))await c.delete(k)})()")
        await page.reload(); await page.wait_for_timeout(5000)
        print('C rounds',await page.evaluate("D.rounds.map(r=>r.key)"),'stored blanks',await page.evaluate("U.add.blanks.length"),'visible mine/core',await page.evaluate("items('blanks').filter(b=>b.mine||b.core).length"),'r02 blank still stored:',await page.evaluate("U.add.blanks.some(b=>b.rk==='r02')"),'qres',await page.evaluate("JSON.stringify(U.qres)"))
        await page.evaluate("saveU()"); await page.wait_for_timeout(1500)
        await page.goto(B+'index.html#stay'); await page.wait_for_timeout(800)
        await page.set_input_files('#zipIn','/home/claude/test/교재_r02.zip'); await page.wait_for_timeout(6000)
        await page.goto(B+'app.html'); await page.wait_for_timeout(5000)
        print('C back: rounds',await page.evaluate("D.rounds.length"),'visible mine/core',await page.evaluate("items('blanks').filter(b=>b.mine||b.core).length"),'r02 mine p',await page.evaluate("items('blanks').filter(b=>b.rk==='r02').map(b=>b.p)"))
        print('errors',errs)
        await b.close()
asyncio.run(main())
